    }

    window.submitComment = async function() {
        var ta = $('commentTextarea');
        if (!ta) return;
        var content = ta.value.trim();
        if (!content) {
            showToast('评论内容不能为空', 'error');
            return;
        }
        if (content.length > 500) {
            showToast('评论内容不能超过500字', 'error');
            return;
        }
        var sb = $('modalSubmitBtn');
        if (sb) {
            sb.disabled = true;
            sb.innerHTML = '<i class="far fa-spinner fa-spin"></i> 发送中...';
        }
        try {
            var res;
            if (C.currentTab === 'paragraph') {
                var fd = new FormData();
                fd.append('post_comment', '1');
                fd.append('content', content);
                fd.append('para_content', C.paraContent || content);
                var qs = new URLSearchParams({
                    book_id: C.bookId,
                    item_id: C.itemId,
                    para: C.para,
                    sessionid: C.sessionid
                }).toString();
                res = await fetchWithKey('?' + qs, {
                    method: 'POST',
                    body: fd
                });
            } else if (C.currentTab === 'chapter') {
                if (!C.relativeId) {
                    showToast('无法获取评论参数', 'error');
