<div class="bottom-comment-bar" id="bottomBar" style="display:none;">
    <input type="text" class="comment-input-trigger" placeholder="写下你的评论..." readonly id="commentTrigger">
    <button class="comment-submit-btn" id="commentSubmitBtn" onclick="openCommentModal()"><i class="far fa-comment"></i>发表</button>
</div>

<div class="comment-modal-overlay" id="commentModalOverlay">
    <div class="comment-modal">
        <div class="modal-header"><div class="modal-title">发表评论</div><button class="modal-close" onclick="closeCommentModal()"><i class="fas fa-times"></i></button></div>
        <div class="modal-body">
            <textarea class="comment-textarea" id="commentTextarea" placeholder="写下你的评论..." maxlength="500"></textarea>
            <div class="emoji-bar" id="emojiBar"></div>
        </div>
        <div class="modal-footer">
            <span class="char-count" id="charCount">0/500</span>
            <button class="modal-submit-btn" id="modalSubmitBtn" onclick="submitComment()"><i class="far fa-paper-plane"></i>发表</button>
        </div>
    </div>
</div>

<div class="toast" id="toast"></div>

