    function applyTheme(d) { document.body.classList.toggle('dark', d); var moon = $('iconMoon'), sun = $('iconSun'); if (moon) moon.style.display = d ? 'none' : ''; if (sun) sun.style.display = d ? '' : 'none'; var meta = $('metaTheme'); if (meta) meta.content = d ? '#1c1c1e' : '#ffffff'; }
