    function processContent(t) { if (!t) return ''; for (var k in EM) { if (!EM.hasOwnProperty(k)) continue; t = t.split(k).join('<img src="'+EM[k]+'" class="bq" alt="'+k+'">'); } return t; }
    function formatTime(ts) { if (!ts) return ''; var d = new Date(ts*1000), n = new Date(), diff = Math.floor((n-d)/1000); if (diff < 60) return '刚刚'; if (diff < 3600) return Math.floor(diff/60)+'分钟前'; if (diff < 86400) return Math.floor(diff/3600)+'小时前'; if (diff < 2592000) return Math.floor(diff/86400)+'天前'; return d.toLocaleDateString('zh-CN'); }
    function showToast(msg, type) { var t = $('toast'); if (!t) return; t.textContent = msg; t.className = 'toast ' + (type || 'success') + ' show'; setTimeout(function() { t.classList.remove('show'); }, 2000); }
