    function loadAndPlayVideo(videoId) { var video = document.getElementById(videoId); if (!video) return; var container = video.parentElement; var placeholder = container.querySelector('.video-placeholder'); var source = video.querySelector('source'); if (!video.src && source && source.dataset.src) { video.src = source.dataset.src; video.load(); video.setAttribute('playsinline', ''); video.setAttribute('webkit-playsinline', ''); if (placeholder) placeholder.style.display = 'none'; video.play().catch(function(e) { if (placeholder) { placeholder.style.display = 'flex'; placeholder.innerHTML = '<div class="play-icon"><i class="fas fa-redo text-white"></i></div><span style="color:#fff;margin-left:8px;">重试</span>'; } }); } else { if (placeholder) placeholder.style.display = 'none'; video.play().catch(function(e) {}); } }
    function buildVideoHtml(commentId, expand) { var videoInfo; try { videoInfo = typeof expand.video_info.video_model === 'string' ? JSON.parse(expand.video_info.video_model) : expand.video_info.video_model; } catch(e) { videoInfo = expand.video_info; } if (!videoInfo) return ''; var posterUrl = videoInfo.first_frame_poster || videoInfo.poster_url || ''; var videoUrl = ''; if (videoInfo.video_list && videoInfo.video_list.video_1 && videoInfo.video_list.video_1.main_url) { try { var eu = videoInfo.video_list.video_1.main_url.replace(/\s/g, ''); videoUrl = atob(eu); if (!videoUrl.startsWith('http')) videoUrl = ''; } catch(e) { if (videoInfo.video_list.video_1.backup_url_1) { try { videoUrl = atob(videoInfo.video_list.video_1.backup_url_1); } catch(e2) {} } } } else if (videoInfo.fallback_api) { videoUrl = videoInfo.fallback_api; } if (!videoUrl) return ''; var videoId = 'video-'+commentId; return '<div class="video-container"><video id="'+videoId+'" controls playsinline webkit-playsinline preload="none" poster="'+posterUrl+'" class="comment-video" crossorigin="anonymous"><source src="" type="video/mp4" data-src="'+videoUrl+'"></video><div class="video-placeholder" onclick="loadAndPlayVideo(\''+videoId+'\')"><div class="play-icon"><i class="fas fa-play text-white text-xl"></i></div></div></div>'; }

    function buildCardBase(user, content, time, badges, likes, extra) { var avatar = user.user_avatar || user.UserHeadIcon || DA; var name = user.user_name || user.UserName || '匿名'; return '<div class="user-row"><div class="avatar-wrap"><img src="'+avatar+'" class="avatar" onerror="this.parentElement.innerHTML=\'<div class=no-avatar><i class=fas fa-user></i></div>\'"></div><div class="user-info"><div class="user-name-row"><span class="user-name">'+name+'</span><span class="user-badges">'+badges+'</span></div></div></div><div class="comment-body">'+content+'</div><div class="comment-footer"><div class="footer-left"><span>'+time+'</span>'+(extra||'')+'</div><div class="like-btn" data-likes="'+likes+'"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 9V5a3 3 0 0 0-3-3l-4 9v11h11.28a2 2 0 0 0 2-1.7l1.38-9a2 2 0 0 0-2-2.3zM7 22H4a2 2 0 0 1-2-2v-7a2 2 0 0 1 2-2h3"/></svg><span>'+likes+'</span></div></div>'; }
    function bindLike(card) { var likeBtn = card.querySelector('.like-btn'); if (!likeBtn) return; likeBtn.addEventListener('click', function(e) { e.stopPropagation(); this.classList.toggle('liked'); var s = this.querySelector('span'), l = parseInt(this.dataset.likes); l = this.classList.contains('liked') ? l+1 : Math.max(0, l-1); s.textContent = l; this.dataset.likes = l; }); }

    function buildReplyItem(r, avatar) { var name = r.user_name || '匿名'; var av = r.user_avatar || avatar || DA; var content = processContent(r.text || ''); var time = formatTime(r.create_timestamp || r.create_time || 0); var likes = r.digg_count || 0; var badges = ''; if (r.is_author || (r.user_info && r.user_info.is_author)) badges += '<span class="user-badge badge-author" style="font-size:9px;padding:1px 4px;">作者</span>'; var div = document.createElement('div'); div.className = 'reply-item'; div.innerHTML = '<div class="reply-user-row"><img src="'+av+'" class="reply-avatar" onerror="this.style.display=\'none\'"><span class="reply-name">'+name+'</span>'+badges+'</div><div class="reply-content">'+content+'</div><div class="reply-footer"><span>'+time+'</span><div class="reply-like" data-likes="'+likes+'"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 9V5a3 3 0 0 0-3-3l-4 9v11h11.28a2 2 0 0 0 2-1.7l1.38-9a2 2 0 0 0-2-2.3zM7 22H4a2 2 0 0 1-2-2v-7a2 2 0 0 1 2-2h3"/></svg><span>'+likes+'</span></div></div>'; var rl = div.querySelector('.reply-like'); if (rl) rl.addEventListener('click', function(e) { e.stopPropagation(); this.classList.toggle('liked'); var s = this.querySelector('span'), l = parseInt(this.dataset.likes); l = this.classList.contains('liked') ? l+1 : Math.max(0, l-1); s.textContent = l; this.dataset.likes = l; }); return div; }

    function addReplySection(card, replyList, avatar) {
        if (!replyList || !replyList.length) return;
        var sec = document.createElement('div'); sec.className = 'reply-section';
        var cnt = replyList.length;
        var tog = document.createElement('div'); tog.className = 'reply-toggle';
        tog.innerHTML = '展开 '+cnt+' 条回复 <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 12 15 18 9"/></svg>';
        var lst = document.createElement('div'); lst.className = 'reply-list'; lst.style.display = 'none';
        replyList.forEach(function(r) { lst.appendChild(buildReplyItem(r, avatar)); });
        tog.addEventListener('click', function() {
            if (lst.style.display === 'none') { lst.style.display = 'block'; tog.classList.add('expanded'); tog.innerHTML = '收起回复 <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 12 15 18 9"/></svg>'; }
            else { lst.style.display = 'none'; tog.classList.remove('expanded'); tog.innerHTML = '展开 '+cnt+' 条回复 <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 12 15 18 9"/></svg>'; }
        });
        sec.appendChild(tog); sec.appendChild(lst); card.appendChild(sec);
    }

    async function fetchWithKey(url, options) {
        options = options || {};
        options.headers = options.headers || {};
        var res = await fetch(url, options);
        var contentType = res.headers.get('content-type') || '';
        if (contentType.includes('text/html')) {
            document.body.innerHTML = await res.text();
            throw new Error('验证失败');
        }
        return res;
    }

async function loadChapter() {
    if (C.isLoading) return;
    C.isLoading = true;
    safeShow('loadingWrap', true);
    safeShow('emptyState', false);
    $('contentArea').innerHTML = '';
    try {
        var res = await fetchWithKey('/get_comment?book_id=' + C.bookId + '&item_id=' + C.itemId + '&offset=' + C.offset + '&count=50');
        var data = await res.json();
        if (data.code === 0) {
            var list = (data.data.mix_data || []).filter(function(i) { return i.data_type === 3; });

            if (list.length === 0) {
                // 明确显示空状态
                safeShow('emptyState', true);
                var emptyText = document.querySelector('#emptyState .empty-text');
                if (emptyText) emptyText.textContent = '暂无章评';
                var cc = $('chapterCount');
                if (cc) cc.textContent = '';
            } else {
                list.forEach(function(item) {
                    var c = item.post_data, u = c.user_info || {};
                    var badges = '';
                    if (u.is_author) badges += '<span class="user-badge badge-author">作者</span>';
                    if (u.is_vip) badges += '<span class="user-badge badge-vip">VIP</span>';
                    var content = processContent(c.pure_content || c.text || '');
                    var time = formatTime(c.create_time || c.create_timestamp);
                    var images = '';
                    try {
                        var cd = JSON.parse(c.content);
                        if (cd.materials) cd.materials.forEach(function(m) {
                            if (m.type === 'img') images += '<img src="' + m.data.web_url + '" class="comment-image" onclick="event.stopPropagation();previewImg(\'' + m.data.web_url + '\')">';
                        });
                    } catch(e) {}
                    var card = document.createElement('div');
                    card.className = 'comment-card';
                    card.innerHTML = buildCardBase(u, content + images, time, badges, c.digg_count || 0, '');
                    bindLike(card);
                    addReplySection(card, c.comment || [], u.user_avatar);
                    $('contentArea').appendChild(card);
                });

                var cc = $('chapterCount'); 
                if (cc) cc.textContent = list.length || '';

                if (list.length > 0 && list[0].post_data && list[0].post_data.relative_id) {
                    C.relativeId = list[0].post_data.relative_id;
                }

                safeShow('emptyState', false);
            }

            C.hasMore = false;
        } else {
            // 接口返回错误
            safeShow('emptyState', true);
            var emptyText = document.querySelector('#emptyState .empty-text');
            if (emptyText) emptyText.textContent = '加载失败，请稍后重试';
            showToast(data.message || '获取章评失败', 'error');
        }
    } catch(e) {
        if (e.message !== '验证失败') {
            safeShow('emptyState', true);
            var emptyText = document.querySelector('#emptyState .empty-text');
            if (emptyText) emptyText.textContent = '网络错误，请检查网络连接';
        }
    } finally {
        safeShow('loadingWrap', false);
        C.isLoading = false;
    }
}

async function loadBook() { 
    if (C.isLoading) return; 
    C.isLoading = true; 
    var isAppend = C.offset > 0;
    if (!isAppend) { 
        safeShow('loadingWrap', true);
        safeShow('emptyState', false);
        $('contentArea').innerHTML = ''; 
    }
    try { 
        var res = await fetchWithKey('/proxy_comments?book_id='+C.bookId+'&offset='+C.offset+'&count=50'); 
        var data = await res.json(); 
        if (data.code === 0) { 
            var list = data.data.comment || []; 
            list.forEach(function(c) { 
                var u = c.user_info || {}; 
                var badges = ''; 
                if (u.is_author) badges += '<span class="user-badge badge-author">作者</span>'; 
                if (u.is_vip) badges += '<span class="user-badge badge-vip">VIP</span>'; 
                if (c.score) badges += '<span class="user-badge badge-score">⭐ '+c.score+'</span>'; 
                var content = processContent(c.text || ''); 
                var time = formatTime(c.create_timestamp); 
                var images = ''; 
                try { 
                    var cd = JSON.parse(c.content); 
                    if (cd.materials) cd.materials.forEach(function(m) { 
                        if (m.type === 'img') images += '<img src="'+m.data.web_url+'" class="comment-image" onclick="event.stopPropagation();previewImg(\''+m.data.web_url+'\')">'; 
                    }); 
                } catch(e) {} 
                var card = document.createElement('div'); 
                card.className = 'comment-card'; 
                card.innerHTML = buildCardBase(u, content+images, time, badges, c.digg_count||0, ''); 
                bindLike(card); 
                addReplySection(card, c.reply_list || [], u.user_avatar); 
                $('contentArea').appendChild(card); 
            }); 
            var bc = $('bookCount'); 
            if (bc) bc.textContent = list.length || ''; 

            // 如果列表为空且不是追加，显示空状态
            if (list.length === 0 && !isAppend) {
                safeShow('emptyState', true);
                var emptyText = document.querySelector('#emptyState .empty-text');
                if (emptyText) emptyText.textContent = '暂无书评';
            }

            C.hasMore = data.data.has_more === true; 
            C.offset = data.data.next_offset !== undefined ? data.data.next_offset : C.offset + 50; 
        } else {
            if (!isAppend) {
                safeShow('emptyState', true);
                var emptyText = document.querySelector('#emptyState .empty-text');
                if (emptyText) emptyText.textContent = '加载失败，请稍后重试';
                showToast(data.message || '获取书评失败', 'error');
            }
        }
    } catch(e) { 
        if (!isAppend) {
            safeShow('emptyState', true);
            var emptyText = document.querySelector('#emptyState .empty-text');
            if (emptyText) emptyText.textContent = '网络错误，请检查网络连接';
        }
    } 
    safeShow('loadingWrap', false);
    if (!document.querySelectorAll('#contentArea .comment-card').length) {
        safeShow('emptyState', true);
    }
    C.isLoading = false; 
}

    function buildParaReplyItem(r) { 
        var ru = (r.Common && r.Common.user_info && r.Common.user_info.base_info) ? r.Common.user_info.base_info : {}; 
        var rut = (r.Common && r.Common.user_info && r.Common.user_info.user_tag) ? r.Common.user_info.user_tag : {}; 
        var rName = ru.user_name || '匿名'; 
        var rAvatar = ru.user_avatar || DA; 
        var rContent = processContent((r.Common && r.Common.content && r.Common.content.text) ? r.Common.content.text : ''); 
        var rTime = formatTime(r.Common ? r.Common.create_timestamp : 0); 
        var rLikes = (r.stat && r.stat.digg_count) ? r.stat.digg_count : 0; 
        var rBadges = ''; 
        if (rut.is_author) rBadges += '<span class="user-badge badge-author" style="font-size:9px;padding:1px 4px;">作者</span>'; 
        if (rut.is_vip) rBadges += '<span class="user-badge badge-vip" style="font-size:9px;padding:1px 4px;">VIP</span>'; 
        if (rut.user_title_info) rut.user_title_info.forEach(function(t) { if (!t.is_author_title && t.zh_title) rBadges += '<span class="user-badge badge-custom" style="font-size:9px;padding:1px 4px;">'+t.zh_title+'</span>'; }); 
        var replyToHtml = ''; 
        if (r.reply_to_user_info && r.reply_to_user_info.base_info && r.reply_to_user_info.base_info.user_name) { 
