                showToast(data.message || '获取书评失败', 'error');
            }
        }
    } catch(e) { 
        if (!isAppend) {
            safeShow('emptyState', true);
            var emptyText = document.querySelector('#emptyState .empty-text');
            if (emptyText) emptyText.textContent = '网络错误，请检查网络连接';
        }
    } 
    safeShow('loadingWrap', false);
    if (!document.querySelectorAll('#contentArea .comment-card').length) {
        safeShow('emptyState', true);
    }
    C.isLoading = false; 
}

    function buildParaReplyItem(r) { 
        var ru = (r.Common && r.Common.user_info && r.Common.user_info.base_info) ? r.Common.user_info.base_info : {}; 
        var rut = (r.Common && r.Common.user_info && r.Common.user_info.user_tag) ? r.Common.user_info.user_tag : {}; 
        var rName = ru.user_name || '匿名'; 
        var rAvatar = ru.user_avatar || DA; 
        var rContent = processContent((r.Common && r.Common.content && r.Common.content.text) ? r.Common.content.text : ''); 
        var rTime = formatTime(r.Common ? r.Common.create_timestamp : 0); 
        var rLikes = (r.stat && r.stat.digg_count) ? r.stat.digg_count : 0; 
        var rBadges = ''; 
        if (rut.is_author) rBadges += '<span class="user-badge badge-author" style="font-size:9px;padding:1px 4px;">作者</span>'; 
        if (rut.is_vip) rBadges += '<span class="user-badge badge-vip" style="font-size:9px;padding:1px 4px;">VIP</span>'; 
        if (rut.user_title_info) rut.user_title_info.forEach(function(t) { if (!t.is_author_title && t.zh_title) rBadges += '<span class="user-badge badge-custom" style="font-size:9px;padding:1px 4px;">'+t.zh_title+'</span>'; }); 
        var replyToHtml = ''; 
        if (r.reply_to_user_info && r.reply_to_user_info.base_info && r.reply_to_user_info.base_info.user_name) { 
            replyToHtml = '<span class="reply-to"> 回复 '+r.reply_to_user_info.base_info.user_name+'</span>'; 
        }
        var replyImages = '';
        var imgs = (r.Common && r.Common.content && r.Common.content.image_data_list && r.Common.content.image_data_list.image_data) 
            ? r.Common.content.image_data_list.image_data : [];
        if (imgs.length > 0) {
            imgs.forEach(function(img) {
                if (img.web_uri) {
                    replyImages += '<img src="'+img.web_uri+'" class="comment-image" style="max-width:40%;max-height:150px;" onclick="event.stopPropagation();previewImg(\''+img.web_uri+'\')">';
                }
            });
        }
        var div = document.createElement('div'); 
        div.className = 'reply-item'; 
        div.innerHTML = '<div class="reply-user-row"><img src="'+rAvatar+'" class="reply-avatar" onerror="this.style.display=\'none\'"><span class="reply-name">'+rName+'</span>'+rBadges+replyToHtml+'</div><div class="reply-content">'+rContent+replyImages+'</div><div class="reply-footer"><span>'+rTime+'</span><div class="reply-like" data-likes="'+rLikes+'"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M14 9V5a3 3 0 0 0-3-3l-4 9v11h11.28a2 2 0 0 0 2-1.7l1.38-9a2 2 0 0 0-2-2.3zM7 22H4a2 2 0 0 1-2-2v-7a2 2 0 0 1 2-2h3"/></svg><span>'+rLikes+'</span></div></div>'; 
        var rl = div.querySelector('.reply-like');
        if (rl) rl.addEventListener('click', function(e) { 
            e.stopPropagation(); this.classList.toggle('liked'); 
            var s = this.querySelector('span'), l = parseInt(this.dataset.likes); 
            l = this.classList.contains('liked') ? l+1 : Math.max(0, l-1); 
            s.textContent = l; this.dataset.likes = l; 
        }); 
        return div; 
    }

    function convertApiReply(r) {
        var userTag = {};
        if (r.user_info) {
            userTag = {
                is_author: r.user_info.is_author || false,
                is_vip: r.user_info.is_vip || false,
                user_title_info: r.user_info.user_sticker ? [{zh_title: r.user_info.user_sticker.sticker ? r.user_info.user_sticker.sticker.name : '', is_author_title: false}] : []
            };
        }
        return {
            Common: {
                user_info: { base_info: r.user_info || {}, user_tag: userTag },
                content: { text: r.text || '', image_data_list: { image_data: (r.image_data || []).map(function(img) { return { web_uri: img.web_uri || '' }; }) } },
                create_timestamp: r.create_timestamp || 0
            },
            stat: { digg_count: r.digg_count || 0 },
            reply_to_reply_id: r.reply_to_reply_id || '0',
            reply_to_user_info: r.reply_to_user_info ? { base_info: r.reply_to_user_info } : null
        };
    }

    async function loadMoreReplies(commentId, listContainer) {
        var cursor = listContainer.dataset.cursor || '0';
        var totalCount = parseInt(listContainer.dataset.totalCount) || 0;
        var oldExtra = listContainer.querySelector('.reply-more-btn');
        if (oldExtra) oldExtra.remove();
        var loading = document.createElement('div');
        loading.className = 'reply-loading reply-more-btn';
        loading.textContent = '加载中...';
        listContainer.appendChild(loading);
        try {
            var res = await fetchWithKey('?reply_api=1&book_id='+C.bookId+'&comment_id='+commentId+'&cursor='+cursor+'&count=20');
            var data = await res.json();
            loading.remove();
            if (data.code === 0 && data.data && data.data.reply_list) {
                var newReplies = data.data.reply_list || [];
                var newCursor = data.data.cursor || '0';
                var hasMore = data.data.has_more || false;
                newReplies.forEach(function(r) {
                    var converted = convertApiReply(r);
                    listContainer.appendChild(buildParaReplyItem(converted));
                });
                listContainer.dataset.cursor = newCursor;
                var newLoadedCount = listContainer.querySelectorAll('.reply-item').length;
                listContainer.dataset.loaded = newLoadedCount >= totalCount ? 'true' : 'false';
                if (hasMore && newLoadedCount < totalCount) {
                    addLoadMoreBtn(commentId, listContainer);
                }
            }
        } catch(e) {
            loading.remove();
            var errDiv = document.createElement('div');
            errDiv.className = 'reply-toggle reply-more-btn';
            errDiv.style.fontSize = '12px';
            errDiv.style.color = '#ef4444';
            errDiv.innerHTML = '加载失败，点击重试';
            errDiv.addEventListener('click', function(e) { e.stopPropagation(); loadMoreReplies(commentId, listContainer); });
            listContainer.appendChild(errDiv);
        }
    }

    function addLoadMoreBtn(commentId, listContainer) {
        var moreBtn = document.createElement('div');
        moreBtn.className = 'reply-toggle reply-more-btn';
        moreBtn.style.fontSize = '12px';
        moreBtn.innerHTML = '加载更多回复...';
        moreBtn.addEventListener('click', function(e) { e.stopPropagation(); loadMoreReplies(commentId, listContainer); });
        listContainer.appendChild(moreBtn);
    }

    function buildParaCard(item) { 
        var c = item.comment, co = c.common || {}, u = co.user_info ? co.user_info.base_info || {} : {}, ut = co.user_info ? co.user_info.user_tag || {} : {}, st = c.stat || {}; 
        var badges = ''; 
        if (ut.is_author) badges += '<span class="user-badge badge-author">作者</span>'; 
        if (ut.is_vip) badges += '<span class="user-badge badge-vip">VIP</span>'; 
        if (ut.user_title_info) ut.user_title_info.forEach(function(t) { if (!t.is_author_title && t.zh_title) badges += '<span class="user-badge badge-custom">'+t.zh_title+'</span>'; }); 
        var content = processContent(co.content ? co.content.text || '' : ''); 
        var time = formatTime(co.create_timestamp); 
        var images = ''; 
        var imgs = co.content && co.content.image_data_list ? co.content.image_data_list.image_data : []; 
        if (imgs && imgs.length) imgs.forEach(function(img) { if (img.web_uri) images += '<img src="'+img.web_uri+'" class="comment-image" onclick="event.stopPropagation();previewImg(\''+img.web_uri+'\')">'; }); 
        var videoHtml = ''; 
        if (c.expand && c.expand.video_info) { videoHtml = buildVideoHtml(c.comment_id, c.expand); } 
        var extra = st.read_duration ? '<span class="dot"></span><span>阅读'+st.read_duration+'s后</span>' : ''; 
        var replyCount = st.reply_count || 0; 
        var card = document.createElement('div'); 
        card.className = 'comment-card'; 
        card.dataset.commentId = c.comment_id;
        card.innerHTML = buildCardBase(u, content+images+videoHtml, time, badges, st.digg_count||0, extra); 
        bindLike(card); 
        var replies = item.replies || [];
        if (replies.length > 0 || replyCount > 0) {
            var sec = document.createElement('div'); 
            sec.className = 'reply-section';
            var tog = document.createElement('div'); 
            tog.className = 'reply-toggle'; 
            tog.innerHTML = '展开 '+replyCount+' 条回复 <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 12 15 18 9"/></svg>'; 
            var lst = document.createElement('div'); 
            lst.className = 'reply-list'; 
            lst.style.display = 'none';
            lst.dataset.loaded = replies.length >= replyCount ? 'true' : 'false';
            lst.dataset.cursor = replies.length > 0 ? String(replies.length) : '0';
            lst.dataset.totalCount = replyCount;
            replies.forEach(function(r) { lst.appendChild(buildParaReplyItem(r)); });
            if (replyCount > replies.length) {
                addLoadMoreBtn(c.comment_id, lst);
            }
            tog.addEventListener('click', function() { 
                if (lst.style.display === 'none') { 
                    lst.style.display = 'block'; 
                    tog.classList.add('expanded'); 
                    tog.innerHTML = '收起回复 <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 12 15 18 9"/></svg>';
                    if (lst.dataset.loaded === 'false') {
                        loadMoreReplies(c.comment_id, lst);
                    }
                } else { 
                    lst.style.display = 'none'; 
                    tog.classList.remove('expanded'); 
                    tog.innerHTML = '展开 '+replyCount+' 条回复 <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="6 9 12 15 18 9"/></svg>'; 
                } 
            }); 
            sec.appendChild(tog); 
            sec.appendChild(lst); 
            card.appendChild(sec); 
        }
        return card; 
    }

    function sortByHot(list) { return list.slice().sort(function(a, b) { return (b.comment && b.comment.stat ? b.comment.stat.digg_count || 0 : 0) - (a.comment && a.comment.stat ? a.comment.stat.digg_count || 0 : 0); }); }

    function renderParaComments(list) { 
        $('contentArea').innerHTML = ''; 
        safeShow('loadingWrap', false);
        if (!list || list.length === 0) { 
