    function loadComments() { if (C.currentTab === 'paragraph') loadParaFromApi(false); else if (C.currentTab === 'book') loadBook(); else loadChapter(); }

    function initEmojiBar() { var bar = $('emojiBar'); if (!bar) return; var html = ''; for (var k in EM) { if (!EM.hasOwnProperty(k)) continue; html += '<div class="emoji-btn-item" data-code="'+k.replace(/"/g,'&quot;')+'" onclick="insertEmoji(\''+k.replace(/'/g,"\\'")+'\')"><img src="'+EM[k]+'" alt="'+k+'"></div>'; } bar.innerHTML = html; }

    function ensureParaContent() {
