                    para: C.para,
                    sessionid: C.sessionid
                }).toString();
                res = await fetchWithKey('?' + qs, {
                    method: 'POST',
                    body: fd
                });
            } else if (C.currentTab === 'chapter') {
                if (!C.relativeId) {
                    showToast('无法获取评论参数', 'error');
                    if (sb) {
                        sb.disabled = false;
                        sb.innerHTML = '<i class="far fa-paper-plane"></i> 发表';
