    var themeToggle = $('themeToggle');
    if (themeToggle) themeToggle.addEventListener('click', toggleTheme);

    document.querySelectorAll('.tab').forEach(function(t) { t.addEventListener('click', function() { switchTab(t.dataset.tab); }); });

    if (C.isParaMode) { 
        var sortBtn = $('sortBtn');
        if (sortBtn) sortBtn.addEventListener('click', toggleSort); 
        document.querySelectorAll('.sort-opt').forEach(function(o) { o.addEventListener('click', function(e) { e.stopPropagation(); selectSort(o.dataset.sort); }); }); 
        document.addEventListener('click', function(e) { 
