        requestAnimationFrame(function() { 
            var st = window.scrollY, wh = window.innerHeight, dh = document.documentElement.scrollHeight; 
            if (dh - st - wh < 500 && !C.isLoading) loadParaFromApi(true); 
            ticking = false; 
        }); 
    }, { passive: true });

    var ticking2 = false;
    window.addEventListener('scroll', function() { 
        if (ticking2 || C.currentTab !== 'book' || !C.hasMore) return; 
        ticking2 = true; 
        requestAnimationFrame(function() { 
            var st = window.scrollY, wh = window.innerHeight, dh = document.documentElement.scrollHeight; 
            if (dh - st - wh < 500 && !C.isLoading) loadBook(); 
            ticking2 = false; 
        }); 
    }, { passive: true });

    initTheme(); 
    initParaToggle(); 
    initEmojiBar();

    var showBar = (C.currentTab === 'paragraph' || C.currentTab === 'chapter');
    safeShow('bottomBar', showBar);
    document.body.style.paddingBottom = showBar ? 'calc(80px + var(--safe-b))' : 'calc(20px + var(--safe-b))';
    loadComments();
})();
